"""Fourth generator: mixed features, nonzero signatures, multi-source, larger K."""
import json, random

NUM = ("TIME", "SIZE", "COUNT")


def gen(rng):
    K = rng.choice([1, 2, 3, 4, 5, 6, 7, 8])
    fields = []
    names = rng.sample(["a", "b", "c", "d", "e", "f", "g", "h"], rng.randint(1, 5))
    for nm in names:
        t = rng.choice(["FLAG", "SIZE", "COUNT", "TIME", "ID", "ID"])
        if t == "FLAG":
            fields.append({"name": nm, "type": "FLAG"})
        elif t == "ID":
            vals = rng.sample(["x", "y", "z", "p.q", "r-s", "t_u"], rng.randint(1, 4))
            fields.append({"name": nm, "type": "ID", "values": vals})
        else:
            lo = rng.choice([0, -3, 5])
            fields.append({"name": nm, "type": t, "min": lo, "max": lo + rng.randint(0, 5)})

    def val(f):
        if f["type"] == "FLAG":
            return rng.random() < 0.6
        if f["type"] == "ID":
            return rng.choice(f["values"])
        return rng.randint(f["min"], f["max"])

    def term(ftype, quant, depth):
        cands = [f for f in fields if f["type"] == ftype]
        r = rng.random()
        if cands and r < 0.55:
            if quant and rng.random() < 0.55:
                return {"field": rng.choice(cands)["name"], "at": "$"}
            return {"field": rng.choice(cands)["name"], "at": rng.randrange(K)}
        if cands and ftype in NUM and depth < 4 and r < 0.8:
            kind = rng.choice(["scale", "add", "sum", "mean", "min", "max"])
            if kind == "scale":
                return {"scale": rng.randint(-3, 5), "term": term(ftype, quant, depth + 1)}
            if kind == "add":
                return {"add": [term(ftype, quant, depth + 1), term(ftype, quant, depth + 1)]}
            f = rng.choice(cands)
            a = rng.randrange(K)
            z = rng.randint(a, K - 1)
            return {"aggregate": kind, "field": f["name"], "from": a, "to": z}
        if ftype == "FLAG":
            return {"const": rng.choice([True, False]), "type": "FLAG"}
        if ftype == "ID":
            pool = set()
            for f in fields:
                if f["type"] == "ID":
                    pool.update(f["values"])
            pool.update(["x", "y", "zz"])
            return {"const": rng.choice(sorted(pool)), "type": "ID"}
        return {"const": rng.randint(-4, 9), "type": ftype}

    atoms = []
    for _ in range(rng.randint(1, 7)):
        ftype = rng.choice([f["type"] for f in fields])
        ops = ["eq", "ne", "lt", "le", "gt", "ge"] if ftype in NUM else ["eq", "ne"]
        body = {"cmp": rng.choice(ops), "left": term(ftype, True, 1), "right": term(ftype, True, 1)}
        if rng.random() < 0.35:
            a = rng.randrange(K)
            z = rng.randint(a, K - 1)
            atoms.append({"quantifier": rng.choice(["any", "all"]), "from": a, "to": z,
                          "predicate": body})
        else:
            # regenerate without $ so it is a plain comparison
            atoms.append({"cmp": body["cmp"], "left": term(ftype, False, 1),
                          "right": term(ftype, False, 1)})
    if atoms and rng.random() < 0.5 and len(atoms) < 20:
        atoms.append(json.loads(json.dumps(rng.choice(atoms))))

    def mk(tid, srcs, nmin, nmax):
        n = rng.randint(nmin, nmax)
        ts = rng.sample(range(-100, 900), n) if n else []
        return {"id": tid, "source": rng.choice(srcs),
                "rows": [{"t": t, "values": [val(f) for f in fields]} for t in ts]}

    nsrc = rng.choice([1, 1, 2, 2, 3, 5])
    srcs = ["s%d" % i for i in range(nsrc)]
    train = [mk("tr%d" % i, srcs, 0 if rng.random() < 0.15 else K, K + rng.randint(0, 6))
             for i in range(rng.randint(0, 4))]
    probes = [mk("pr%d" % i, srcs, 1, 4) for i in range(rng.randint(0, 3))]
    queries = [mk("q%d" % i, srcs, 0, 5) for i in range(rng.randint(0, 3))]
    return {"version": 1, "window": K, "schema": fields, "atoms": atoms,
            "policy": {"max_width": rng.choice([1, 2, 2, 3, 3, 4]),
                       "min_support": rng.choice([1, 1, 1, 2, 3, 5]),
                       "min_witness": rng.choice([1, 1, 1, 2, 3])},
            "train": train, "probes": probes, "queries": queries}
PYEOF
